package cn.sixnine.filmlog;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

/** Layout and route checks in an isolated workspace, never production records. */
public final class AlignmentInstrumentation extends Instrumentation {
 interface Action{void run()throws Exception;} Activity current;int checks;Configuration original;
 void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 void main(Action a)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{a.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new RuntimeException(error[0]);}
 Object call(Object o,String name,Class<?>[] types,Object...args)throws Exception{java.lang.reflect.Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
 View root(){return ((ViewGroup)current.findViewById(android.R.id.content)).getChildAt(0);}
 ArrayList<View> all(View v){ArrayList<View> list=new ArrayList<>();list.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)list.addAll(all(((ViewGroup)v).getChildAt(i)));return list;}
 View text(String label){for(View v:all(root()))if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return v;return null;}
 int dp(int n){return LibraryUi.dp(current,n);}
 void layout(int w){View r=root();r.measure(View.MeasureSpec.makeMeasureSpec(dp(w),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(dp(820),View.MeasureSpec.EXACTLY));r.layout(0,0,r.getMeasuredWidth(),r.getMeasuredHeight());}
 void header(){ViewGroup r=(ViewGroup)root(),h=r.findViewWithTag("library-header");check(h!=null,"shared header "+current.getClass().getSimpleName());Rect box=new Rect();h.getDrawingRect(box);r.offsetDescendantRectToMyCoords(h,box);check(Math.abs(box.left-r.getPaddingLeft())<=1||box.left==0,"header left screen alignment: "+box);check(Math.abs(box.right-(r.getWidth()-r.getPaddingRight()))<=1||box.right==r.getWidth(),"header right screen alignment: "+box);if(((ViewGroup.MarginLayoutParams)h.getLayoutParams()).leftMargin<0)check(!((ViewGroup)h.getParent()).getClipToPadding(),"navigation not clipped by content padding");check(h.getHeight()==dp(56),"56dp navigation");View left=h.getChildAt(1),title=h.getChildAt(0);check(left.getLeft()==0&&left.getWidth()==dp(48),"48dp back region");check(Math.abs(title.getLeft()+title.getWidth()/2f-h.getWidth()/2f)<=1,"centered title");if(h.getChildCount()>2){View right=h.getChildAt(2);check(right.getRight()==h.getWidth()&&right.getWidth()==left.getWidth(),"symmetric actions");check(right.getTop()==left.getTop()&&right.getHeight()==left.getHeight(),"same vertical alignment");}}
 void launch(Class<?> type,Intent extras)throws Exception{current=startActivitySync(extras.setClass(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->{for(int width:new int[]{320,375,414}){layout(width);header();}root().requestLayout();});}
 void finishPage()throws Exception{main(()->current.finish());}
 void snap(String name)throws Exception{waitForIdleSync();SystemClock.sleep(150);Bitmap b=getUiAutomation().takeScreenshot();File dir=new File(getTargetContext().getFilesDir(),"alignment");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;Context target=getTargetContext();String prior=Workspace.current(target);try{
 check(target.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated package");Workspace.activate(target,UUID.randomUUID().toString());Context c=Workspace.context(target);String roll;try(LogStore logs=new LogStore(c)){roll=new CatalogStore(logs).manual(UUID.randomUUID().toString(),"Layout test","Kodak Gold 200","Nikon FE2",200,36,"35 mm","","");for(int i=0;i<17;i++)logs.insert(roll,1793100000000L+i*60000,0,480,"denied","8","1/125","","","","");}
 for(int mode=0;mode<4;mode++){launch(PhotoToolsActivity.class,new Intent().putExtra("tool_mode",mode));original=new Configuration(current.getResources().getConfiguration());for(boolean dark:new boolean[]{false,true})for(float scale:new float[]{1f,1.6f}){final int selected=mode;main(()->{Configuration cfg=new Configuration(original);cfg.uiMode=(cfg.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);cfg.fontScale=scale;cfg.screenWidthDp=320;current.getResources().updateConfiguration(cfg,current.getResources().getDisplayMetrics());call(current,"show",new Class<?>[]{});for(int width:new int[]{320,375,414}){layout(width);header();if(selected==0){ViewGroup group=root().findViewWithTag("exposure-priority");check(group!=null,"priority selector");for(int i=0;i<2;i++){View choice=group.getChildAt(i);check(choice.getElevation()==0&&choice.getStateListAnimator()==null,"no clipped shadow");check(choice.getTop()>=dp(3)&&choice.getBottom()<=group.getHeight()-dp(3),"selection inset");check(choice.getWidth()>dp(100),"usable option");}}}root().requestLayout();});if(scale==1)snap("tool-"+mode+(dark?"-dark":"-light"));}main(()->{current.getResources().updateConfiguration(original,current.getResources().getDisplayMetrics());current.finish();});}
 launch(ExposureTimerActivity.class,new Intent());finishPage();launch(RemindersActivity.class,new Intent());finishPage();launch(BackupActivity.class,new Intent());finishPage();for(String tab:new String[]{"gear","stock","project"}){launch(CatalogActivity.class,new Intent().putExtra("tab",tab));finishPage();}launch(StockLibraryActivity.class,new Intent());finishPage();launch(ScansActivity.class,new Intent().putExtra("roll",roll));finishPage();
 launch(StatsActivity.class,new Intent());main(()->{layout(375);View a=text("选择年份，查看年度回顾"),b=text("更多统计与统计说明");check(a!=null&&b!=null,"stats actions");check(b.getTop()-a.getBottom()>=dp(12),"stats actions12dp gap");check(a.getTop()-((ViewGroup)a.getParent()).getChildAt(((ViewGroup)a.getParent()).indexOfChild(a)-2).getBottom()>=dp(12),"rank to actions gap");root().requestLayout();});snap("statistics");main(()->{for(View v:all(root()))if(v instanceof ScrollView)((ScrollView)v).fullScroll(View.FOCUS_DOWN);});snap("statistics-actions");main(()->call(current,"openAchievements",new Class<?>[]{}));main(()->{layout(375);header();});finishPage();
 current=startActivitySync(new Intent(target,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->call(current,"openSettings",new Class<?>[]{}));main(()->{layout(375);header();check(text("使用说明")==null,"removed usage entry");check(text("版本说明")!=null,"release notes entry");root().requestLayout();});snap("settings");main(()->call(current,"showVersionNotes",new Class<?>[]{}));snap("version-notes");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);finishPage();
 out.putString("stream","PASS "+checks+" assertions: shared navigation geometry, tools in two themes/1.0 and1.6 fonts at320/375/414; inset unshadowed priority selection; 12dp stats gaps; settings notes/removal; timer/reminders/backup/catalog/library/scans/achievement routes.\n");ok=true;
 }catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));}finally{try{if(current!=null)main(()->{if(original!=null)current.getResources().updateConfiguration(original,current.getResources().getDisplayMetrics());current.finish();});Workspace.activate(target,prior);}catch(Exception ignored){}}finish(ok?-1:0,out);}
}
